/**
 * Errors crossing the FFI boundary. Each variant carries a message the UI can
 * show; the variant tells the UI how to react (re-auth, retry, give up).
 */
public enum CoreError: Swift.Error {

    
    
    /**
     * The server rejected the credentials.
     */
    case Auth(message: String
    )
    /**
     * No JMAP server could be found for the address.
     */
    case Discovery(message: String
    )
    /**
     * Transport failure; retrying later may succeed.
     */
    case Network(message: String
    )
    /**
     * The server answered with a JMAP or HTTP error.
     */
    case Server(message: String
    )
    /**
     * Local database failure.
     */
    case Storage(message: String
    )
    case NotFound(message: String
    )
    case InvalidInput(message: String
    )
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeCoreError: FfiConverterRustBuffer {
    typealias SwiftType = CoreError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> CoreError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Auth(
            message: try FfiConverterString.read(from: &buf)
            )
        case 2: return .Discovery(
            message: try FfiConverterString.read(from: &buf)
            )
        case 3: return .Network(
            message: try FfiConverterString.read(from: &buf)
            )
        case 4: return .Server(
            message: try FfiConverterString.read(from: &buf)
            )
        case 5: return .Storage(
            message: try FfiConverterString.read(from: &buf)
            )
        case 6: return .NotFound(
            message: try FfiConverterString.read(from: &buf)
            )
        case 7: return .InvalidInput(
            message: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: CoreError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .Auth(message):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Discovery(message):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Network(message):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Server(message):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .Storage(message):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .NotFound(message):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(message, into: &buf)
            
        
        case let .InvalidInput(message):
            writeInt(&buf, Int32(7))
            FfiConverterString.write(message, into: &buf)
            
        }
    }
}


